function App() {
  const rows = [
    ["fetch(url)", "cached forever (until revalidated) → SSG"],
    ["fetch(url, { next: { revalidate: 60 } })", "ISR: refresh after 60s"],
    ["fetch(url, { next: { tags: ['posts'] } })", "taggable: purge via revalidateTag"],
    ["fetch(url, { cache: 'no-store' })", "never cached → dynamic (SSR)"],
  ];
  return (
    <table style={{ fontFamily: 'ui-monospace, monospace', fontSize: 12, padding: 16, borderCollapse: 'collapse' }}>
      <tbody>
        {rows.map(([a, b]) => (
          <tr key={a}>
            <td style={{ paddingRight: 16, verticalAlign: 'top' }}>{a}</td>
            <td style={{ color: '#475569' }}>{b}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function App() {
  const [log, setLog] = useState([]);
  function run() {
    const calls = [];
    const cache = new Map();
    let network = 0;
    const memoFetch = (url) => {
      if (cache.has(url)) { calls.push('memo HIT  ' + url); return cache.get(url); }
      network++;
      calls.push('network   ' + url);
      const v = 'data:' + url;
      cache.set(url, v);
      return v;
    };
    memoFetch('/api/user'); // layout
    memoFetch('/api/user'); // page (deduped)
    memoFetch('/api/cart'); // different
    calls.push('--- network calls this render: ' + network + ' ---');
    setLog(calls);
  }
  return (
    <div style={{ fontFamily: 'ui-monospace, monospace', fontSize: 12, padding: 16 }}>
      <button onClick={run}>Render once</button>
      <pre>{log.join('\n')}</pre>
    </div>
  );
}

