function App() {
  const code = [
    "// app/actions.ts",
    "'use server';",
    "import { revalidateTag } from 'next/cache';",
    "export async function publish(formData) {",
    "  await db.post.create({ data: ... });",
    "  revalidateTag('posts'); // purge Data + Full Route cache for tagged fetches",
    "}",
  ];
  return <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>{code.join('\n')}</pre>;
}

// app/blog/page.tsx (Server Component)
export default async function BlogPage() {
  const posts = await fetch('https://api/posts', {
    next: { tags: ['posts'], revalidate: 3600 },
  }).then((r) => r.json());
  return <PostList posts={posts} />;
}

// app/actions.ts
'use server';
import { revalidateTag } from 'next/cache';
import { db } from '@/lib/db';

export async function publishPost(formData: FormData) {
  await db.post.create({ data: { title: String(formData.get('title')) } });
  // Purge every fetch tagged 'posts' (Data Cache) and dependent routes (Full Route Cache)
  revalidateTag('posts');
}
